const item = $input.item.json;

let rawContent = item.text || '';

let cleanedText = String(rawContent)
  .replace(/```json/gi, '')
  .replace(/```/g, '')
  .trim();

const jsonMatch = cleanedText.match(/\{[\s\S]*\}/);

if (jsonMatch) cleanedText = jsonMatch[0];

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const cleaned = String(value).replace(/[^0-9.-]/g, '');
  if (!cleaned || cleaned === '-') return null;
  const number = parseFloat(cleaned);
  return Number.isFinite(number) ? number : null;
}

function cleanString(value) {
  if (value === null || value === undefined) return null;
  const valueString = String(value).trim();
  return valueString === '' ? null : valueString;
}

function matches(a, b) {
  if (a === null || b === null) return false;
  return Math.abs(a - b) <= 0.02;
}

let parsed = {};
let parseError = null;
try { parsed = JSON.parse(cleanedText); } catch (e) { parseError = e.message; }

const cleaned = {
  supplier_name: cleanString(parsed.supplier_name),
  invoice_number: cleanString(parsed.invoice_number),
  invoice_date: cleanString(parsed.invoice_date),
  due_date: cleanString(parsed.due_date),
  subtotal: toNumber(parsed.subtotal),
  tax_amount: toNumber(parsed.tax_amount),
  total_amount: toNumber(parsed.total_amount),
  line_items: Array.isArray(parsed.line_items) ? parsed.line_items.map(line => ({
    description: cleanString(line.description),
    quantity: toNumber(line.quantity),
    unit_price: toNumber(line.unit_price),
    amount: toNumber(line.amount)
  })) : []
};

const errors = [];
if (parseError) errors.push('Invalid JSON returned by AI');
if (!cleaned.supplier_name) errors.push('Missing supplier name');
if (!cleaned.invoice_number) errors.push('Missing invoice number');
if (!cleaned.invoice_date) errors.push('Missing invoice date');
if (!cleaned.due_date) errors.push('Missing due date');
if (cleaned.subtotal === null) errors.push('Missing subtotal');
if (cleaned.tax_amount === null) errors.push('Missing tax amount');
if (cleaned.total_amount === null) errors.push('Missing total amount');

if (!cleaned.line_items.length) {
  errors.push('No line items found');
} else {
  cleaned.line_items.forEach((line, index) => {
    const n = index + 1;
    if (!line.description) errors.push(`Line ${n}: missing description`);
    if (line.quantity === null) errors.push(`Line ${n}: missing quantity`);
    if (line.unit_price === null) errors.push(`Line ${n}: missing unit price`);
    if (line.amount === null) errors.push(`Line ${n}: missing amount`);
    if (line.quantity !== null && line.unit_price !== null && line.amount !== null) {
      const expected = line.quantity * line.unit_price;
      if (!matches(expected, line.amount)) errors.push(`Line ${n}: quantity × unit price does not equal amount`);
    }
  });
}

if (cleaned.line_items.length > 0 && cleaned.line_items.every(line => line.amount !== null) && cleaned.subtotal !== null) {
  const calculatedSubtotal = cleaned.line_items.reduce((sum, line) => sum + line.amount, 0);
  if (!matches(calculatedSubtotal, cleaned.subtotal)) errors.push('Subtotal does not match line items');
}

if (cleaned.subtotal !== null && cleaned.tax_amount !== null && cleaned.total_amount !== null) {
  const calculatedTotal = cleaned.subtotal + cleaned.tax_amount;
  if (!matches(calculatedTotal, cleaned.total_amount)) errors.push('Subtotal + tax does not equal total');
}

let sourceFilename = 'unknown';
try {
  const binary = $('Webhook Trigger').first().binary;
  const key = Object.keys(binary || {})[0];
  if (key && binary[key].fileName) sourceFilename = binary[key].fileName;
} catch (e) {}

return [{ json: { ...cleaned, source_filename: sourceFilename, processed_at: new Date().toISOString(), valid: !parseError && errors.length === 0, error_reason: errors.length ? errors.join('; ') : null, validation_errors: errors, raw_ai_response: rawContent } }];
